CREATE TABLE `tickets` (`id` INT NOT NULL AUTO_INCREMENT , `code` VARCHAR(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL , `path` VARCHAR(100) NOT NULL , `is_active` BOOLEAN NOT NULL DEFAULT FALSE , PRIMARY KEY (`id`), INDEX (`code`) USING BTREE) ENGINE = InnoDB;
ALTER TABLE `tickets` ADD `action_id` INT NOT NULL AFTER `id`, ADD INDEX (`action_id`) USING BTREE;
ALTER TABLE `tickets` ADD FOREIGN KEY (`action_id`) REFERENCES `actions`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;